//go:build ppc64le

package floats

// VSX Abs, Neg, Square, Floor, Ceil, Trunc and RoundEven kernels (round.go,
// POWER8 baseline, gated on hasVSX), generated by go-asmgen (round_ppc64le_gen.go)
// into round_ppc64le.s. A kernel does the whole blocks of eight elements; the Go
// code finishes the last seven with the scalar expression.
//
//go:noescape
func absVSX(dst, src *float64, n int)

//go:noescape
func negVSX(dst, src *float64, n int)

//go:noescape
func squareVSX(dst, src *float64, n int)

//go:noescape
func floorVSX(dst, src *float64, n int)

//go:noescape
func ceilVSX(dst, src *float64, n int)

//go:noescape
func truncVSX(dst, src *float64, n int)

//go:noescape
func rintVSX(dst, src *float64, n int)

func vabs(dst, src []float64) {
	n := len(src) &^ 7
	if n == 0 || !hasVSX {
		absRef(dst, src)
		return
	}
	absVSX(&dst[0], &src[0], n)
	absRef(dst[n:], src[n:])
}

